import json, random, subprocess, sys

random.seed(1234)
BASE = ("MESSAGE sip:inbox@relay.test SIP/2.0\r\n"
        "From: \"A, visitor\" <SIP:%65mber@STUDIO.TEST.>;tag=q7\r\n"
        "To: <sip:inbox@relay.test>\r\n"
        "Call-ID: sample-73\r\n"
        "CSeq: 0009 MESSAGE\r\n"
        "P-Asserted-Identity: <sip:desk@sales.test>\r\n"
        "Content-Type: text/plain\r\n"
        "Content-Length: 5\r\n\r\nhello")
CHARS = list("<>@;:,.=\"'\\ \t\r\n/*+!%_~()[]0123456789abcXYZ") + ["\x00","\x7f","\xe9","\r\n\r\n","sip:","tel:+1","anonymous.invalid","\ud800"]
def mutate(s):
    s=list(s)
    for _ in range(random.randint(1,6)):
        op=random.choice(["del","ins","rep","dup"])
        if not s: break
        i=random.randrange(len(s))
        if op=="del": del s[i]
        elif op=="ins": s.insert(i, random.choice(CHARS))
        elif op=="rep": s[i]=random.choice(CHARS)
        else: s[i:i]=s[max(0,i-10):i]
    return "".join(s)

DIR={"sip:ember@studio.test":["sip:e1@alias.studio.test","tel:+12025550121"],"sip:desk@sales.test":["tel:+12025550122"]}
ACC={"session-k":{"primary":"sip:ember@studio.test","allow":["sip:desk@sales.test"]}}
GW={"edge":{"local_domains":["studio.test","sales.test"],"peers":{}},
    "inside":{"local_domains":[],"peers":{"edge":["studio.test","sales.test"]}}}

bad=0
for round_ in range(40):
    jobs=[]
    for i in range(200):
        raw=mutate(BASE)
        jobs.append({"gateway":"edge","ingress":{"kind":"local","subject":"session-k"},"trusted_out":True,"raw":raw})
        if i%3==0:
            jobs.append({"gateway":"inside","ingress":{"kind":"peer","name":"edge"},"trusted_out":True,"raw":mutate(BASE)})
        if i%5==0:
            jobs.append({"gateway":"edge","ingress":{"kind":"untrusted"},"trusted_out":False,"raw":raw})
        if i%7==0:
            jobs.append({"gateway":"edge","ingress":{"kind":"local","subject":"session-k"},"trusted_out":True,"source":i})
    batch={"directory":DIR,"accounts":ACC,"gateways":GW,"jobs":jobs}
    data=json.dumps(batch).encode("utf-8","surrogatepass")
    out=subprocess.run([sys.executable,"/workspace/submission/gateway.py"],input=data,capture_output=True)
    if out.returncode!=0:
        bad+=1
        print("CRASH round",round_,out.returncode, out.stderr.decode()[:2000]); break
    try:
        res=json.loads(out.stdout)
        assert isinstance(res,dict) and list(res.keys())==["results"]
        assert len(res["results"])==len(jobs), (len(res["results"]),len(jobs))
        for r in res["results"]:
            if r["status"]=="accept":
                assert set(r)=={"status","identity","basis","private","wire"}
                assert r["basis"] in ("local","peer") and isinstance(r["private"],bool)
                assert isinstance(r["wire"],str) and r["wire"].endswith("\r\n\r\nhello") or True
            else:
                assert set(r)=={"status","reason"} and r["reason"] in ("upstream","syntax","unauthenticated","identity")
    except Exception as e:
        bad+=1; print("BAD OUTPUT",round_,e); print(out.stdout[:500]); break
print("fuzz done, failures:",bad)
PYEOF
python3 tmp/fuzz.py
